import type {
  AssetAlias,
  EmbeddingRecord,
  ModelState,
  Store,
  Task,
  TaskFilter,
} from '@sequel/core';
import { getCloudflareContext } from '@opennextjs/cloudflare';

/**
 * The Forge store, on D1.
 *
 * The file driver that came before it kept everything in one JSON snapshot
 * written by the process serving the request. That works for `pnpm dev` and
 * cannot work here: a Worker has no writable disk, and the memory fallback
 * gives every isolate its own copy — so an image generated by one isolate was
 * an "Unknown or expired asset id" to the next one that tried to serve it.
 *
 * Each row carries the whole object as JSON next to the handful of columns
 * worth querying on. That keeps the schema from having to track every field
 * in @sequel/core, and filtering still happens in SQL rather than by loading
 * the table and sorting it in the Worker — which is the other thing the file
 * driver did, and the reason the tasks list would have got slower every week.
 */

/** Resolved per call: the binding belongs to the request, not to the module. */
async function db(): Promise<D1Database> {
  const { env } = await getCloudflareContext({ async: true });
  if (!env.DB) throw new Error('D1 binding DB is missing.');
  return env.DB;
}

export class D1Store implements Store {
  async listTasks(filter?: TaskFilter): Promise<Task[]> {
    const where: string[] = [];
    const binds: unknown[] = [];

    // Strict equality, so an unassigned run is visible to no organisation
    // rather than to all of them.
    if (filter?.organizationId) {
      where.push('organization_id = ?');
      binds.push(filter.organizationId);
    }
    if (filter?.createdByUserId) {
      where.push('created_by_user_id = ?');
      binds.push(filter.createdByUserId);
    }
    // ISO-8601 sorts lexicographically, so these are plain string compares.
    if (filter?.createdAfter) {
      where.push('created_at >= ?');
      binds.push(filter.createdAfter);
    }
    if (filter?.createdBefore) {
      where.push('created_at <= ?');
      binds.push(filter.createdBefore);
    }
    if (filter?.ids?.length) {
      where.push(`id IN (${filter.ids.map(() => '?').join(',')})`);
      binds.push(...filter.ids);
    }
    if (filter?.status?.length) {
      where.push(`status IN (${filter.status.map(() => '?').join(',')})`);
      binds.push(...filter.status);
    }
    if (filter?.models?.length) {
      where.push(`model IN (${filter.models.map(() => '?').join(',')})`);
      binds.push(...filter.models);
    }

    let sql = `SELECT data FROM task${where.length ? ` WHERE ${where.join(' AND ')}` : ''} ORDER BY created_at DESC`;

    /* SQLite needs a LIMIT before it will take an OFFSET; -1 means 'all of
       them', which is what an offset with no limit asks for. */
    if (filter?.limit !== undefined || filter?.offset) {
      sql += ' LIMIT ?';
      binds.push(filter.limit ?? -1);
    }
    if (filter?.offset) {
      sql += ' OFFSET ?';
      binds.push(filter.offset);
    }

    const { results } = await (await db())
      .prepare(sql)
      .bind(...binds)
      .all<{ data: string }>();

    return results.map((row) => JSON.parse(row.data) as Task);
  }

  async getTask(id: string): Promise<Task | undefined> {
    const row = await (await db())
      .prepare('SELECT data FROM task WHERE id = ?')
      .bind(id)
      .first<{ data: string }>();
    return row ? (JSON.parse(row.data) as Task) : undefined;
  }

  async putTask(task: Task): Promise<void> {
    await (await db())
      .prepare(
        `INSERT INTO task (id, organization_id, created_by_user_id, model, status, created_at, data)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET
           organization_id = excluded.organization_id,
           created_by_user_id = excluded.created_by_user_id,
           model = excluded.model,
           status = excluded.status,
           created_at = excluded.created_at,
           data = excluded.data`,
      )
      .bind(
        task.id,
        task.organizationId ?? null,
        task.createdBy?.userId ?? null,
        task.model,
        task.status,
        task.createdAt,
        JSON.stringify(task),
      )
      .run();
  }

  /**
   * Read, merge, write.
   *
   * Not a transaction: D1 has no interactive ones, and the only writer that
   * races here is a provider poll updating the task it owns. A lost update
   * would cost one status refresh, which the next poll repairs.
   */
  async patchTask(id: string, patch: Partial<Task>): Promise<Task | undefined> {
    const current = await this.getTask(id);
    if (!current) return undefined;
    const next = { ...current, ...patch } as Task;
    await this.putTask(next);
    return next;
  }

  async getModelStates(): Promise<ModelState[]> {
    const { results } = await (await db())
      .prepare('SELECT id, enabled FROM model_state')
      .all<{ id: string; enabled: number }>();
    return results.map((row) => ({ id: row.id, enabled: row.enabled === 1 }));
  }

  async setModelEnabled(id: string, enabled: boolean): Promise<void> {
    await (await db())
      .prepare(
        `INSERT INTO model_state (id, enabled) VALUES (?, ?)
         ON CONFLICT(id) DO UPDATE SET enabled = excluded.enabled`,
      )
      .bind(id, enabled ? 1 : 0)
      .run();
  }

  async putAlias(alias: AssetAlias): Promise<void> {
    await (await db())
      .prepare(
        `INSERT INTO asset_alias (id, data, created_at) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET data = excluded.data, created_at = excluded.created_at`,
      )
      .bind(alias.id, JSON.stringify(alias), alias.createdAt)
      .run();
  }

  async getAlias(id: string): Promise<AssetAlias | undefined> {
    const row = await (await db())
      .prepare('SELECT data FROM asset_alias WHERE id = ?')
      .bind(id)
      .first<{ data: string }>();
    return row ? (JSON.parse(row.data) as AssetAlias) : undefined;
  }

  async read(): Promise<EmbeddingRecord[]> {
    const { results } = await (await db())
      .prepare('SELECT id, hash, model, vector FROM embedding')
      .all<{ id: string; hash: string; model: string; vector: string }>();
    return results.map((row) => ({
      id: row.id,
      hash: row.hash,
      model: row.model,
      vector: JSON.parse(row.vector) as number[],
    }));
  }

  /**
   * The cache is written whole, so this replaces the table — but only the
   * rows that changed are rewritten, because the index is re-embedded on
   * every cold start and rewriting a few hundred vectors each time would be
   * the most expensive thing the app does.
   */
  async write(records: EmbeddingRecord[]): Promise<void> {
    const connection = await db();
    const existing = new Map(
      (
        await connection
          .prepare('SELECT id, hash FROM embedding')
          .all<{ id: string; hash: string }>()
      ).results.map((row) => [row.id, row.hash]),
    );

    const statements = [];
    const keep = new Set<string>();

    for (const record of records) {
      keep.add(record.id);
      if (existing.get(record.id) === record.hash) continue;
      statements.push(
        connection
          .prepare(
            `INSERT INTO embedding (id, hash, model, vector) VALUES (?, ?, ?, ?)
             ON CONFLICT(id) DO UPDATE SET
               hash = excluded.hash, model = excluded.model, vector = excluded.vector`,
          )
          .bind(record.id, record.hash, record.model, JSON.stringify(record.vector)),
      );
    }

    // A model that left the catalogue leaves its vector behind otherwise.
    const stale = [...existing.keys()].filter((id) => !keep.has(id));
    if (stale.length > 0) {
      statements.push(
        connection
          .prepare(`DELETE FROM embedding WHERE id IN (${stale.map(() => '?').join(',')})`)
          .bind(...stale),
      );
    }

    if (statements.length > 0) await connection.batch(statements);
  }
}
